{{velocity}} ## Inputs: ## - $changeItems ## - $displayEditLink #foreach ($item in $changeItems) #loadChangeView($item, $displayEditLink) ## A change with no title is given no section of its own (see #loadChangeView). #if ($title != '') === $title${displayEditLinkMarkup}=== #end ## The edit link of a change with no title reaches the summary line through a variable rather than through a ## directive closing that line: Velocity drops the newline ending a line that ends with a directive. The blank ## line that follows then closes the paragraph the summary is rendered in, which the screenshots below must not ## be part of: the gallery they are displayed in is a standalone macro and cannot be used inline. $changeSummary$summaryEditLinkMarkup
#if ("$changeObject.getValue('screenshots')" != '') #displayScreenshots($changeObject, true, false)
#end #if ($moreDetailsLinkMarkup != '') $moreDetailsLinkMarkup #end #end {{/velocity}}
